using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Windows.Forms;
namespace Synkoz {
 public static class Language945 {
  static readonly string settings=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Snkoz","language.txt");
  public static bool Translating;public static bool English=File.Exists(settings)&&File.ReadAllText(settings).Trim()=="en";
  static readonly Dictionary<string,string> words=new Dictionary<string,string>();static readonly HashSet<Control> watched=new HashSet<Control>();static readonly HashSet<Form> forms=new HashSet<Form>();
  public static void Set(bool english){Directory.CreateDirectory(Path.GetDirectoryName(settings));File.WriteAllText(settings,english?"en":"fr");Synkoz.ErrorR8.Show(english?"Restart Snkoz to apply English.":"Relancer Snkoz pour utiliser le français.","Snkoz");}
  public static void Start(){string file=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"English.tsv");if(File.Exists(file))foreach(var line in File.ReadAllLines(file)){int at=line.IndexOf('\t');if(at>0)words[line.Substring(0,at).Replace("\\n","\n")]=line.Substring(at+1).Replace("\\n","\n");}Application.Idle+=delegate{if(!English)return;foreach(Form form in Application.OpenForms.Cast<Form>().ToArray())if(forms.Add(form)){Apply(form);form.FormClosed+=delegate{forms.Remove(form);};}};}
  public static string T(string text){if(!English||string.IsNullOrEmpty(text))return text;string result;if(words.TryGetValue(text,out result))return result;int dot=text.IndexOf(" · ");if(text.StartsWith("K")&&dot>0)return text.Substring(0,dot+3)+T(text.Substring(dot+3));int marker=text.IndexOf(" - ");if(marker>0&&words.TryGetValue(text.Substring(marker+3),out result))return text.Substring(0,marker+3)+result;foreach(var p in words.OrderByDescending(p=>p.Key.Length))if(p.Key.EndsWith(" ")&&text.StartsWith(p.Key,StringComparison.Ordinal))return p.Value+text.Substring(p.Key.Length);return text;}
  public static void Apply(Control control){if(!watched.Add(control))return;control.Disposed+=delegate{watched.Remove(control);};if(control is TextBoxBase||control is NumericUpDown)return;var list=control as ListControl;if(list==null){bool changing=false;control.Text=T(control.Text);control.TextChanged+=delegate{if(changing)return;string translated=T(control.Text);if(translated!=control.Text){changing=true;try{control.Text=translated;}finally{changing=false;}}};}if(list!=null){Translating=true;try{list.Format+=delegate(object sender,ListControlConvertEventArgs e){e.Value=T(Convert.ToString(e.Value));};}finally{Translating=false;}}control.ControlAdded+=delegate(object s,ControlEventArgs e){if(control.IsHandleCreated)control.BeginInvoke(new Action(delegate{if(!e.Control.IsDisposed)Apply(e.Control);}));};foreach(Control child in control.Controls)Apply(child);}
  public static void Menu(ToolStrip menu){foreach(ToolStripItem item in menu.Items)item.Text=T(item.Text);}
 }
}
